/* ============================================================
   هسته: تاریخ شمسی، ابزارها، اعداد فارسی
   ============================================================ */
'use strict';
const COMPANY_DEFAULT = 'شرکت دام و طیور سپید بستک';

const J = (() => {
  const breaks = [-61, 9, 38, 199, 426, 686, 756, 818, 1111, 1181, 1210, 1635, 2060, 2097, 2192, 2262, 2324, 2394, 2456, 3178];
  const div = (a, b) => ~~(a / b);
  const mod = (a, b) => a - ~~(a / b) * b;
  function jalCal(jy, withoutLeap) {
    const bl = breaks.length, gy = jy + 621;
    let leapJ = -14, jp = breaks[0], jm, jump = 0, leap, n, i;
    for (i = 1; i < bl; i += 1) {
      jm = breaks[i]; jump = jm - jp;
      if (jy < jm) break;
      leapJ = leapJ + div(jump, 33) * 8 + div(mod(jump, 33), 4);
      jp = jm;
    }
    n = jy - jp;
    leapJ = leapJ + div(n, 33) * 8 + div(mod(n, 33) + 3, 4);
    if (mod(jump, 33) === 4 && jump - n === 4) leapJ += 1;
    const leapG = div(gy, 4) - div((div(gy, 100) + 1) * 3, 4) - 150;
    const march = 20 + leapJ - leapG;
    if (withoutLeap) return { gy, march };
    if (jump - n < 6) n = n - jump + div(jump + 4, 33) * 33;
    leap = mod(mod(n + 1, 33) - 1, 4);
    if (leap === -1) leap = 4;
    return { leap, gy, march };
  }
  function g2d(gy, gm, gd) {
    let d = div((gy + div(gm - 8, 6) + 100100) * 1461, 4) + div(153 * mod(gm + 9, 12) + 2, 5) + gd - 34840408;
    d = d - div(div(gy + 100100 + div(gm - 8, 6), 100) * 3, 4) + 752;
    return d;
  }
  function d2g(jdn) {
    let j = 4 * jdn + 139361631;
    j = j + div(div(4 * jdn + 183187720, 146097) * 3, 4) * 4 - 3908;
    const i = div(mod(j, 1461), 4) * 5 + 308;
    const gd = div(mod(i, 153), 5) + 1;
    const gm = mod(div(i, 153), 12) + 1;
    const gy = div(j, 1461) - 100100 + div(8 - gm, 6);
    return { gy, gm, gd };
  }
  function j2d(jy, jm, jd) {
    const r = jalCal(jy, true);
    return g2d(r.gy, 3, r.march) + (jm - 1) * 31 - div(jm, 7) * (jm - 7) + jd - 1;
  }
  function d2j(jdn) {
    const gy = d2g(jdn).gy;
    let jy = gy - 621;
    const r = jalCal(jy, false);
    const jdn1f = g2d(gy, 3, r.march);
    let k = jdn - jdn1f, jm, jd;
    if (k >= 0) {
      if (k <= 185) { jm = 1 + div(k, 31); jd = mod(k, 31) + 1; return { jy, jm, jd }; }
      k -= 186;
    } else { jy -= 1; k += 179; if (r.leap === 1) k += 1; }
    jm = 7 + div(k, 30); jd = mod(k, 30) + 1;
    return { jy, jm, jd };
  }
  const isLeap = (jy) => jalCal(jy, false).leap === 0;
  const monthLength = (jy, jm) => jm <= 6 ? 31 : jm <= 11 ? 30 : (isLeap(jy) ? 30 : 29);
  const months = ['فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند'];
  const weekdays = ['شنبه', 'یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه'];

  function fromDate(dt) { const d = g2d(dt.getFullYear(), dt.getMonth() + 1, dt.getDate()); return d2j(d); }
  function pad(n) { return String(n).padStart(2, '0'); }
  function fmt(o) { return `${o.jy}/${pad(o.jm)}/${pad(o.jd)}`; }
  function today() { return fmt(fromDate(new Date())); }
  function parse(s) {
    if (!s) return null;
    const m = String(toEn(s)).trim().match(/^(\d{2,4})[\/\.\-](\d{1,2})[\/\.\-](\d{1,2})$/);
    if (!m) return null;
    let jy = +m[1]; const jm = +m[2], jd = +m[3];
    if (jy < 100) jy += 1400;
    if (jm < 1 || jm > 12 || jd < 1 || jd > monthLength(jy, jm)) return null;
    return { jy, jm, jd };
  }
  function norm(s) { const o = parse(s); return o ? fmt(o) : null; }
  function toDay(s) { const o = parse(s); return o ? j2d(o.jy, o.jm, o.jd) : null; }
  function fromDay(d) { return fmt(d2j(d)); }
  function todayDay() { const n = new Date(); return g2d(n.getFullYear(), n.getMonth() + 1, n.getDate()); }
  function weekday(o) { const d = j2d(o.jy, o.jm, o.jd); const g = d2g(d); const wd = new Date(g.gy, g.gm - 1, g.gd).getDay(); return (wd + 1) % 7; }
  function long(s) { const o = parse(s); if (!o) return s || ''; return `${o.jd} ${months[o.jm - 1]} ${o.jy}`; }
  function monthKey(s) { const o = parse(s); return o ? `${o.jy}/${pad(o.jm)}` : null; }
  return { j2d, d2j, g2d, d2g, isLeap, monthLength, months, weekdays, fromDate, fmt, today, parse, norm, toDay, fromDay, todayDay, weekday, long, monthKey, pad };
})();

/* ---------- اعداد ---------- */
const FA_DIG = '۰۱۲۳۴۵۶۷۸۹', AR_DIG = '٠١٢٣٤٥٦٧٨٩';
function toEn(s) {
  return String(s ?? '').replace(/[۰-۹]/g, d => FA_DIG.indexOf(d)).replace(/[٠-٩]/g, d => AR_DIG.indexOf(d));
}
function toFa(s) { return String(s ?? '').replace(/\d/g, d => FA_DIG[d]); }
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(toEn(v).replace(/[,\s٬]/g, ''));
  return Number.isFinite(n) ? n : null;
}
function nf(n, digits = 0) {
  if (n === null || n === undefined || !Number.isFinite(+n)) return '—';
  return toFa((+n).toLocaleString('en-US', { maximumFractionDigits: digits, minimumFractionDigits: 0 })).replace(/,/g, '٬');
}
function pct(a, b, d = 1) { if (!b) return '۰٪'; return toFa(((a / b) * 100).toFixed(d).replace(/\.0$/, '')) + '٪'; }

/* ---------- ابزار عمومی ---------- */
function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function uid(p = 'x') { return p + Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }
function clone(o) { return JSON.parse(JSON.stringify(o)); }
function by(key, dir = 1) { return (a, b) => (a[key] > b[key] ? dir : a[key] < b[key] ? -dir : 0); }
function debounce(fn, ms) { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; }
function $(sel, root = document) { return root.querySelector(sel); }
function $$(sel, root = document) { return Array.from(root.querySelectorAll(sel)); }
function normText(s) {
  return toEn(String(s ?? '')).toLowerCase()
    .replace(/[يى]/g, 'ی').replace(/ك/g, 'ک').replace(/[‌‏ً-ٟ]/g, '')
    .replace(/\s+/g, ' ').trim();
}
function matches(hay, q) { if (!q) return true; const h = normText(hay); return normText(q).split(' ').every(w => h.includes(w)); }
function ordinal(n) { const w = ['اولین', 'دومین', 'سومین', 'چهارمین', 'پنجمین', 'ششمین', 'هفتمین', 'هشتمین', 'نهمین', 'دهمین']; return n >= 1 && n <= 10 ? w[n - 1] : toFa(n) + '‌امین'; }
function meta(...parts) { return parts.filter(Boolean).map(p => `<bdi>${p}</bdi>`).join('<span class="sep">·</span>'); }
function nowStamp() {
  const d = new Date();
  return `${J.today()} ${J.pad(d.getHours())}:${J.pad(d.getMinutes())}`;
}

