/* ساختن نسخه دیگری از یک فهرست با تغییرات */
function variantParts(base, mods) {
  const out = {};
  Object.keys(base).forEach(k => { out[k] = base[k].map(r => r.slice()); });
  Object.entries(mods).forEach(([sys, m]) => {
    if (m.replace) { out[sys] = m.replace.map(r => r.slice()); return; }
    let list = out[sys] || (out[sys] = []);
    if (m.set) Object.entries(m.set).forEach(([name, row]) => { const i = list.findIndex(r => r[0] === name); if (i >= 0) list[i] = row; else list.push(row); });
    if (m.drop) { list = list.filter(r => !m.drop.includes(r[0])); out[sys] = list; }
    if (m.add) list.push(...m.add);
  });
  return out;
}

