function newMachineRec(nm, supervisorId = 'p8', pmId = 'p9') {
  return {
    id: nm.id, code: nm.code, type: nm.type, plate: '', model: nm.model, driverId: '', floating: true,
    supervisorId, pmId, unit: 'hour', odometer: null, odoDate: null, note: 'راننده ثابت ندارد', active: true,
  };
}
/* افزودن لودرها و تراکتورها به داده‌های قبلی (بدون دست زدن به اطلاعات ثبت‌شده) */
function addFleet2(d) {
  NEW_MODELS.forEach(md => {
    if (!d.models.some(x => x.id === md.id)) d.models.push(clone(md));
    if (!d.catalog[md.id] || !d.catalog[md.id].length) d.catalog[md.id] = buildCatalog(md.id);
  });
  const sup = d.people.find(p => p.role === 'supervisor' && p.active !== false) || {};
  const pm = d.people.find(p => p.role === 'pm' && p.active !== false) || {};
  NEW_MACHINES.forEach(nm => {
    const exists = d.machines.some(m => {
      const t = normText(`${m.code} ${m.type || ''}`).replace(/\s+/g, '');
      return nm.match.every(k => t.includes(k));
    });
    if (exists) return;
    const rec = newMachineRec(nm, sup.id || '', pm.id || '');
    if (d.machines.some(m => m.id === rec.id)) rec.id = uid('m');
    d.machines.push(rec);
  });
}

function buildCatalog(modelId) {
  const extra = EXTRA_PARTS[modelId];
  const tw = extra ? {} : (MODEL_TWEAKS[modelId] || {});
  const srcParts = extra || BASE_PARTS;
  const out = [];
  SYSTEMS.forEach(sys => {
    const t = tw[sys.key] || {};
    let i = 0;
    (srcParts[sys.key] || []).forEach(([name, km, mo, act, note]) => {
      if (t.drop && t.drop.includes(name)) return;
      i++;
      out.push({
        id: `${modelId}-${sys.key}-${String(i).padStart(2, '0')}`,
        sys: sys.key,
        name: (t.rename && t.rename[name]) || name,
        km, mo, act, note, cons: '',
        alts: [],
      });
    });
  });
  return out;
}

/* ارتقای داده‌ها به نسخه ۳:
   - مراحل ده‌گانه وضعیت به چهار مرحله نگاشت می‌شوند
   - فهرست قطعات (نگهداری پیشگیرانه و جایگزین‌ها) خالی می‌شود تا کاربر خودش وارد کند؛
     سوابق تعویض با نام قطعه نگه داشته می‌شوند تا در تاریخچه ماشین بمانند */
function migrateV3(d) {
  const mp = (n) => OLD_STAGE_MAP[n] || n;
  (d.repairs || []).forEach(r => {
    (r.track || []).forEach(e => {
      const o = e.n;
      e.n = mp(o);
      if (o === 6 && e.part) e.part.step = 'arrived';
      if (o === 8 && !r.doneDate) r.doneDate = e.date;
      if (o !== e.n) e.oldN = o;
    });
  });
  (d.users || []).forEach(u => { if (Array.isArray(u.stages)) u.stages = [...new Set(u.stages.map(mp))].sort((a, b) => a - b); });
  (d.smsLog || []).forEach(x => { if (x.n) x.n = mp(x.n); });
  d.settings = d.settings || {};
  d.settings.stageCfg = {};
  if (d.settings.sms && d.settings.sms.rules) d.settings.sms.rules = {};
  const names = {};
  Object.entries(d.catalog || {}).forEach(([mid, list]) => (list || []).forEach(p => { names[p.id] = { name: p.name, sys: p.sys, act: p.act }; }));
  (d.partLogs || []).forEach(l => { const x = names[l.partId]; if (x && !l.partName) { l.partName = x.name; l.partSys = x.sys; l.partAct = x.act; } });
  Object.keys(d.catalog || {}).forEach(k => { d.catalog[k] = []; });
}

/* ارتقا به نسخه ۴: مراحل قابل تعریف با شناسه ثابت
   - نام‌ها و حد مجازی که کاربر قبلاً در تنظیمات عوض کرده بود حفظ می‌شود */
function migrateV4(d) {
  const base = clone(STAGE_DEFAULTS);
  const cfg = (d.settings && d.settings.stageCfg) || {};
  base.forEach((s, i) => {
    const c = cfg[i + 1] || {};
    if (String(c.label || '').trim()) s.label = String(c.label).trim();
    if (c.limit !== undefined && i > 0 && i < base.length - 1) s.limit = c.limit;
  });
  d.settings.stages = base;
  d.settings.stageCfg = {};
  const sidOf = (n) => SID_BY_OLDN[(+n || 1) - 1] || 'wait';
  (d.repairs || []).forEach(r => (r.track || []).forEach(e => {
    if (!e.sid) { e.sid = sidOf(e.n); e.label = (base.find(x => x.sid === e.sid) || {}).label || ''; }
  }));
  (d.users || []).forEach(u => { if (Array.isArray(u.stages)) u.stages = [...new Set(u.stages.map(x => typeof x === 'number' ? sidOf(x) : x))]; });
  (d.smsLog || []).forEach(x => { if (x.n && !x.sid) x.sid = sidOf(x.n); });
  const sms = d.settings.sms || {};
  if (sms.rules && typeof sms.rules === 'object') {
    const nr = {};
    Object.entries(sms.rules).forEach(([k, v]) => { nr[/^\d+$/.test(k) ? sidOf(+k) : k] = v; });
    sms.rules = nr;
  }
}

