/* ============================================================
   بایگانی تعمیرات: پرونده‌هایی که تست سلامتشان ثبت شده
   ============================================================ */
const ArchState = { q: '', machine: '', result: '', from: '', to: '' };
Pages.archive = () => {
  const d = Store.get();
  const all = d.repairs.filter(r => Track.closed(r)).sort((a, b) => (b.returnDate || '').localeCompare(a.returnDate || '') || (b.updatedAt || '').localeCompare(a.updatedAt || ''));
  const f = J.norm(ArchState.from), t = J.norm(ArchState.to);
  const list = all.filter(r => {
    if (ArchState.machine && r.machineId !== ArchState.machine) return false;
    if (ArchState.result && Track.testResult(r) !== ArchState.result) return false;
    if (f && (r.returnDate || '') < f) return false;
    if (t && (r.returnDate || '') > t) return false;
    if (ArchState.q && !matches(`${r.type} ${r.diagnoser} ${r.shop} ${r.repairerNote} ${r.note} ${(r.test || {}).note || ''} ${(Q.machine(r.machineId) || {}).code || ''}`, ArchState.q)) return false;
    return true;
  });
  const c = { all: all.length, pass: 0, fail: 0, old: 0 };
  all.forEach(r => { c[Track.testResult(r)]++; });
  const tile = (k, label, n, tone, ic) => `<button class="sum-tile ${tone} ${ArchState.result === k ? 'on' : ''}" data-res="${k}"><b>${nf(n)}</b><span>${icon(ic)}${label}</span></button>`;
  const perM = d.machines.map(m => ({ m, n: all.filter(r => r.machineId === m.id).length })).filter(x => x.n);
  const rows = list.map(r => {
    const m = Q.machine(r.machineId) || {};
    const down = Rep.downDays(r);
    return `<tr class="row-link" data-href="#/repairs/${r.id}">
      <td class="num-cell muted">${r.no ? toFa(r.no) : ''}</td>
      <td class="nowrap"><b class="mcode">${esc(m.code || '—')}</b></td>
      <td class="cell-topic"><b>${esc(r.type || '—')}</b>${r.repairerNote ? `<small>تعمیرکار: ${esc(r.repairerNote)}</small>` : ''}${r.prevId ? `<small>${icon('link')}ادامه خرابی قبلی</small>` : ''}</td>
      <td class="nowrap">${toFa(r.reportDate || '—')}</td>
      <td class="nowrap">${r.referDate ? toFa(r.referDate) : '<span class="muted">—</span>'}</td>
      <td class="nowrap">${r.doneDate ? toFa(r.doneDate) : '<span class="muted">—</span>'}</td>
      <td class="nowrap">${toFa(r.returnDate || '—')}</td>
      <td>${testPill(r)}</td>
      <td class="nowrap">${down !== null ? nf(down) + ' روز' : '—'}</td>
    </tr>`;
  }).join('');
  const html = `
    <div class="sum-tiles">
      ${tile('', 'همه پرونده‌های بایگانی', c.all, 'muted', 'archive')}
      ${tile('pass', 'تست سلامت قبول', c.pass, 'good', 'circle-check')}
      ${tile('fail', 'تست سلامت رد', c.fail, 'crit', 'circle-x')}
      ${tile('old', 'قبل از راه‌اندازی تست', c.old, 'muted', 'history')}
    </div>
    ${perM.length ? `<div class="chips-row"><button class="chip ${!ArchState.machine ? 'on' : ''}" data-m="">همه ماشین‌ها</button>${perM.map(x => `<button class="chip ${ArchState.machine === x.m.id ? 'on' : ''}" data-m="${x.m.id}"><bdi>${esc(x.m.code)}</bdi> (${nf(x.n)})</button>`).join('')}</div>` : ''}
    <div class="filters card">
      <div class="field grow"><span class="field-label">جستجو</span><div class="input-ic">${icon('search')}<input class="input" name="q" placeholder="نوع خرابی، تعمیرگاه، شرح تست…" value="${esc(ArchState.q)}"></div></div>
      ${F.field('از تاریخ تست', F.date('from', ArchState.from))}
      ${F.field('تا تاریخ', F.date('to', ArchState.to))}
    </div>
    <section class="card flush">
      ${all.length ? (list.length ? `<div class="table-wrap"><table class="table rep-table">
        <thead><tr><th>شماره</th><th>ماشین</th><th>نوع خرابی</th><th>اعلام</th><th>ارسال برای تعمیر</th><th>پایان تعمیر</th><th>تست سلامت</th><th>نتیجه</th><th>مدت توقف</th></tr></thead>
        <tbody>${rows}</tbody></table></div><div class="table-foot">${nf(list.length)} پرونده از ${nf(all.length)}</div>`
      : emptyState('search-x', 'پرونده‌ای با این فیلترها پیدا نشد'))
      : emptyState('archive', 'بایگانی هنوز خالی است', 'هر خرابی بعد از ثبت «تست سلامت» در کارخانه، اینجا بایگانی می‌شود.')}
    </section>
    ${ArchState.machine ? `<a class="card arch-link" href="#/machines/${ArchState.machine}">${icon('history')}<span><b>تاریخچه کامل ${esc((Q.machine(ArchState.machine) || {}).code || '')}</b><small>خرابی‌ها، تست‌ها، تحلیل‌ها، تعویض قطعات و کارکرد — همه در یک صفحه</small></span>${icon('chevron-left')}</a>` : ''}`;
  return {
    title: 'بایگانی تعمیرات',
    sub: 'پرونده خرابی‌هایی که تست سلامتشان در کارخانه ثبت شده است؛ هیچ پرونده‌ای پاک نمی‌شود',
    actions: `<button class="btn btn-ghost" data-csv ${list.length ? '' : 'disabled'}>${icon('file-spreadsheet')}خروجی اکسل</button><button class="btn btn-ghost" data-print ${list.length ? '' : 'disabled'}>${icon('printer')}چاپ گزارش</button>`,
    html,
    mount(el) {
      const q = el.querySelector('input[name=q]');
      q.addEventListener('input', debounce(() => { ArchState.q = q.value; App.rerender(); setTimeout(() => { const nq = $('input[name=q]'); if (nq) { nq.focus(); nq.setSelectionRange(nq.value.length, nq.value.length); } }, 0); }, 300));
      el.querySelectorAll('input[data-date]').forEach(x => x.addEventListener('change', () => { ArchState[x.name] = toEn(x.value); App.rerender(); }));
      el.querySelectorAll('[data-res]').forEach(b => b.addEventListener('click', () => { ArchState.result = ArchState.result === b.dataset.res ? '' : b.dataset.res; App.rerender(); }));
      el.querySelectorAll('[data-m]').forEach(b => b.addEventListener('click', () => { ArchState.machine = b.dataset.m; App.rerender(); }));
      el.querySelector('[data-csv]').addEventListener('click', () => exportRepairsCSV(list));
      el.querySelector('[data-print]').addEventListener('click', () => printRepairsReport(list, 'بایگانی تعمیرات' + (ArchState.machine ? ' · ماشین: ' + ((Q.machine(ArchState.machine) || {}).code || '') : '')));
      bindRowLinks(el);
    },
  };
};

