/* ============================================================
   تاریخچه کامل یک ماشین: همه رویدادهای ثبت‌شده در یک خط زمانی
   ============================================================ */
const HIST_KINDS = {
  rep: { label: 'خرابی و تعمیر', icon: 'wrench' },
  test: { label: 'تست سلامت', icon: 'stethoscope' },
  an: { label: 'تحلیل خرابی', icon: 'clipboard-list' },
  pm: { label: 'نگهداری و تعویض قطعه', icon: 'gauge' },
  odo: { label: 'کارکرد', icon: 'activity' },
};
const HistState = { id: null, kind: '', more: false };
function machineHistory(id) {
  const d = Store.get();
  const m = Q.machine(id) || {};
  const ev = [];
  d.repairs.filter(r => r.machineId === id).forEach(r => {
    Track.history(r).forEach(e => {
      const sg = Track.stageOf(e);
      const isTest = sg.kind === 'test';
      const res = isTest ? Track.testResult(r) : '';
      ev.push({
        kind: isTest ? 'test' : 'rep', date: e.date || '', at: e.at || '',
        title: sg.kind === 'report' ? `${sg.label}: ${r.type || ''}` : isTest ? `${sg.label}: ${res === 'old' ? 'بسته شده (قبل از تست)' : (TEST_RES[res] || {}).short || ''}` : `${sg.label}`,
        sub: [sg.kind !== 'report' ? r.type : '', e.note && e.note !== r.type ? e.note : '', e.part && e.part.name ? 'منتظر: ' + e.part.name : '', e.shop ? e.shop : '', e.byName ? 'ثبت: ' + e.byName : ''].filter(Boolean).join(' · '),
        href: `#/repairs/${r.id}`, tone: isTest ? (res === 'fail' ? 'crit' : res === 'pass' ? 'good' : 'muted') : sg.kind === 'report' ? 'warn' : 'info',
      });
    });
  });
  d.analyses.filter(a => a.machineId === id).forEach(a => {
    const rs = Logic.resultOf(a);
    ev.push({ kind: 'an', date: a.date || '', at: a.createdAt || '', title: `تحلیل خرابی: ${a.topic || ''}`, sub: `${(RESULTS[rs] || {}).label || ''}${a.severity && SEV[a.severity] ? ' · ' + SEV[a.severity].label : ''}`, href: `#/analyses/${a.id}`, tone: rs === 'none' ? 'good' : 'crit' });
  });
  d.partLogs.filter(l => l.machineId === id).forEach(l => {
    const p = Q.part(m.model, l.partId);
    const name = p ? p.name : (l.partName || 'قطعه حذف‌شده');
    const act = ACT_TYPES[p ? p.act : l.partAct] || ACT_TYPES.r;
    ev.push({ kind: 'pm', date: l.date || '', at: l.at || '', title: `${act.label}: ${name}`, sub: [l.km !== null && l.km !== undefined ? `${nf(l.km)} ${unitLabel(m)}` : '', l.note || '', !p ? 'از فهرست قبلی قطعات' : ''].filter(Boolean).join(' · '), href: `#/maint/${id}`, tone: 'info' });
  });
  d.odoLogs.filter(o => o.machineId === id).forEach(o => ev.push({ kind: 'odo', date: o.date || '', at: '', title: `ثبت کارکرد: ${nf(o.value)} ${unitLabel(m)}`, sub: '', href: '', tone: 'muted' }));
  return ev.sort((a, b) => (b.date || '').localeCompare(a.date || '') || (b.at || '').localeCompare(a.at || ''));
}
function machineHistoryCard(id) {
  if (HistState.id !== id) { HistState.id = id; HistState.kind = ''; HistState.more = false; }
  const all = machineHistory(id);
  const list = all.filter(e => !HistState.kind || e.kind === HistState.kind);
  const shown = HistState.more ? list : list.slice(0, 30);
  const chips = [['', 'همه', all.length], ...Object.entries(HIST_KINDS).map(([k, v]) => [k, v.label, all.filter(e => e.kind === k).length])].filter(x => x[0] === '' || x[2])
    .map(([k, l, n]) => `<button class="chip ${HistState.kind === k ? 'on' : ''}" data-hk="${k}">${k ? icon(HIST_KINDS[k].icon) : ''}${l} (${nf(n)})</button>`).join('');
  let lastMonth = '';
  const items = shown.map(e => {
    const mo = (e.date || '').slice(0, 7);
    const head = mo && mo !== lastMonth ? `<li class="hist-month">${toFa(J.long((mo + '/01')).replace(/^\S+\s/, '') || mo)}</li>` : '';
    lastMonth = mo || lastMonth;
    const inner = `<span class="mh-ic tone-${e.tone}">${icon(HIST_KINDS[e.kind].icon)}</span><span class="mh-main"><b>${esc(e.title)}</b>${e.sub ? `<small>${esc(e.sub)}</small>` : ''}</span><span class="mh-date">${toFa(e.date || '—')}</span>`;
    return head + `<li class="mh-item">${e.href ? `<a href="${e.href}">${inner}</a>` : `<div>${inner}</div>`}</li>`;
  }).join('');
  return `<section class="card mh-card" id="hist">
    <div class="card-head"><h3>${icon('history')}تاریخچه کامل ماشین (بایگانی)</h3><div class="head-acts"><span class="muted small">هر چیزی که برای این ماشین ثبت شود اینجا می‌ماند</span><button class="btn btn-sm btn-ghost" data-hprint>${icon('printer')}چاپ</button></div></div>
    <div class="chips-row">${chips}</div>
    ${list.length ? `<ol class="mh-list">${items}</ol>${list.length > shown.length ? `<button class="btn btn-ghost full" data-hmore>${icon('chevron-down')}نمایش ${nf(list.length - shown.length)} مورد دیگر</button>` : ''}` : emptyState('history', 'هنوز چیزی برای این ماشین ثبت نشده')}
  </section>`;
}
function bindMachineHistory(el, id) {
  el.querySelectorAll('[data-hk]').forEach(b => b.addEventListener('click', () => { HistState.kind = b.dataset.hk; HistState.more = false; App.rerender(); }));
  const mb = el.querySelector('[data-hmore]'); if (mb) mb.addEventListener('click', () => { HistState.more = true; App.rerender(); });
  const pb = el.querySelector('[data-hprint]'); if (pb) pb.addEventListener('click', () => {
    const m = Q.machine(id) || {};
    const list = machineHistory(id).filter(e => !HistState.kind || e.kind === HistState.kind);
    const html = `<div class="pr-doc">
      ${Printer.head('تاریخچه ماشین ' + esc(m.code || ''), HistState.kind ? esc(HIST_KINDS[HistState.kind].label) : 'همه رویدادها', `<span>تعداد: ${toFa(list.length)}</span>`)}
      <table class="pr-table"><thead><tr><th class="c">ش</th><th>تاریخ</th><th>نوع</th><th>شرح</th><th>جزئیات</th></tr></thead>
      <tbody>${list.map((e, i) => `<tr><td class="c">${toFa(i + 1)}</td><td class="nw">${pv(e.date)}</td><td class="nw">${esc(HIST_KINDS[e.kind].label)}</td><td>${esc(e.title)}</td><td>${esc(e.sub || '')}</td></tr>`).join('')}</tbody></table>
      ${Printer.signs(['مسئول ماشین‌آلات', 'سرپرست', 'مدیریت'])}
      ${Printer.foot()}
    </div>`;
    Printer.run(html, { title: 'تاریخچه ' + (m.code || '') });
  });
}

/* ============================================================
   پشتیبان‌گیری و بازیابی
   ============================================================ */
function backupPayload() { return { app: 'fleet-maint', version: 1, exportedAt: new Date().toISOString(), exportedAtFa: nowStamp(), data: Store.get() }; }
function exportBackup() {
  const stamp = nowStamp().replace(/[\/: ]/g, '-');
  downloadBlob(`پشتیبان-سامانه-ناوگان-${stamp}.json`, new Blob([JSON.stringify(backupPayload(), null, 1)], { type: 'application/json' }));
  Store.update(d => { d.settings.lastExportAt = nowStamp(); }, { system: true });
  Toast.show('فایل پشتیبان دانلود شد');
}
function parseBackup(text) {
  const o = JSON.parse(text);
  const data = o && o.app === 'fleet-maint' ? o.data : o;
  if (!data || !Array.isArray(data.machines) || !Array.isArray(data.analyses) || !data.catalog) throw new Error('این فایل، پشتیبان معتبر این سامانه نیست');
  return { data, when: o.exportedAtFa || o.exportedAt || '' };
}
function dataStats(d) {
  const alts = Object.values(d.catalog || {}).reduce((s, l) => s + l.reduce((a, p) => a + (p.alts || []).length, 0), 0);
  const parts = Object.values(d.catalog || {}).reduce((s, l) => s + l.length, 0);
  return { machines: d.machines.length, people: d.people.length, repairs: (d.repairs || []).length, analyses: d.analyses.length, logs: d.partLogs.length, parts, alts };
}
function statsList(s) {
  return `<ul class="stats-list">
    <li><span>${icon('truck')}ماشین‌آلات</span><b>${nf(s.machines)}</b></li>
    <li><span>${icon('wrench')}خرابی‌ها و تعمیرات</span><b>${nf(s.repairs || 0)}</b></li>
    <li><span>${icon('users')}پرسنل</span><b>${nf(s.people)}</b></li>
    <li><span>${icon('clipboard-list')}تحلیل‌های خرابی</span><b>${nf(s.analyses)}</b></li>
    <li><span>${icon('wrench')}سوابق تعویض قطعات</span><b>${nf(s.logs)}</b></li>
    <li><span>${icon('package')}قطعات در فهرست</span><b>${nf(s.parts)}</b></li>
    <li><span>${icon('arrow-left-right')}قطعات جایگزین ثبت‌شده</span><b>${nf(s.alts)}</b></li>
  </ul>`;
}

Pages.backup = () => {
  const d = Store.get();
  const h = App.backupHealth();
  const s = dataStats(d);
  const size = new Blob([JSON.stringify(d)]).size;
  const ab = AutoBackup;
  const autoBody = !ab.supported
    ? `<div class="notice notice-warn">${icon('triangle-alert')}<span>این مرورگر از ذخیره خودکار در پوشه پشتیبانی نمی‌کند. برای این قابلیت سایت را با <b>Google Chrome</b> یا <b>Microsoft Edge</b> باز کنید. تا آن زمان از «پشتیبان دستی» استفاده کنید.</span></div>`
    : ab.state === 'on'
      ? `<div class="auto-on"><span class="pulse"></span><div><b>فعال است</b><small>پوشه: ${esc(ab.folderName)}${d.settings.lastAutoBackupAt ? ' · آخرین ذخیره: ' + toFa(d.settings.lastAutoBackupAt) : ''}</small></div></div>
         <div class="btn-row"><button class="btn btn-soft" data-auto-now>${icon('refresh-cw')}ذخیره همین حالا</button><button class="btn btn-ghost" data-auto-choose>${icon('folder-open')}تغییر پوشه</button><button class="btn btn-ghost danger-text" data-auto-off>${icon('power')}غیرفعال کردن</button></div>`
      : ab.state === 'needs-permission'
        ? `<div class="notice notice-warn">${icon('triangle-alert')}<span>مرورگر پس از هر بار باز شدن سایت، برای نوشتن در پوشه «${esc(ab.folderName)}» دوباره اجازه می‌خواهد.</span></div>
           <div class="btn-row"><button class="btn btn-primary" data-auto-re>${icon('shield-check')}اجازه دسترسی و ادامه پشتیبان خودکار</button><button class="btn btn-ghost" data-auto-choose>${icon('folder-open')}انتخاب پوشه دیگر</button></div>`
        : `<p class="muted">یک پوشه انتخاب کنید (ترجیحاً روی فلش، درایو دیگر یا پوشه‌ای که در شبکه همگام می‌شود). از این به بعد پس از هر تغییر، فایل «پشتیبان-آخرین.json» و یک فایل روزانه به تاریخ همان روز در آن پوشه ذخیره می‌شود.</p>
           <div class="btn-row"><button class="btn btn-primary" data-auto-choose>${icon('folder-open')}انتخاب پوشه پشتیبان</button></div>`;

  const html = `
    <section class="card backup-hero tone-${h.tone}">
      <div class="bh-ic">${icon(h.tone === 'good' ? 'shield-check' : 'shield-alert')}</div>
      <div class="bh-main"><h2>${h.title}</h2><p>${h.sub}</p>
        <p class="muted small">همه اطلاعات سایت فقط روی همین کامپیوتر و داخل مرورگر ذخیره می‌شود. اگر حافظه مرورگر پاک شود یا ویندوز عوض شود، فقط با فایل پشتیبان قابل بازگشت است.</p></div>
      <button class="btn btn-primary btn-lg" data-export>${icon('download')}دریافت فایل پشتیبان</button>
    </section>

    <div class="grid-2">
      <section class="card">
        <div class="card-head"><h3>${icon('folder-sync')}پشتیبان خودکار در پوشه</h3></div>
        ${autoBody}
      </section>
      <section class="card">
        <div class="card-head"><h3>${icon('upload')}بازیابی از فایل پشتیبان</h3></div>
        <label class="drop" id="drop">
          <input type="file" accept=".json,application/json" hidden id="restoreFile">
          ${icon('file-up')}<b>فایل پشتیبان را اینجا رها کنید</b><span>یا برای انتخاب فایل کلیک کنید (.json)</span>
        </label>
        <p class="muted small">پیش از بازیابی، از وضعیت فعلی یک نسخه داخلی خودکار ذخیره می‌شود تا در صورت اشتباه قابل برگشت باشد.</p>
      </section>
    </div>

    <div class="grid-main">
      <section class="card">
        <div class="card-head"><h3>${icon('history')}نسخه‌های داخلی (بازگشت به گذشته)</h3><button class="btn btn-sm btn-ghost" data-snap>${icon('plus')}ذخیره نسخه همین حالا</button></div>
        <p class="muted small">سایت هر روز یک نسخه از داده‌ها را داخل مرورگر نگه می‌دارد (تا ۲۰ نسخه آخر). این نسخه‌ها جایگزین فایل پشتیبان نیستند چون در همان مرورگر ذخیره می‌شوند.</p>
        <div id="snaps"><div class="skeleton"></div></div>
      </section>
      <div class="stack">
        <section class="card">
          <div class="card-head"><h3>${icon('database')}اطلاعات ذخیره‌شده</h3></div>
          ${statsList(s)}
          <div class="muted small">حجم داده‌ها: ${nf(size / 1024, 1)} کیلوبایت${d.settings.lastExportAt ? ` · آخرین پشتیبان دستی: ${toFa(d.settings.lastExportAt)}` : ''}</div>
        </section>
        <section class="card">
          <div class="card-head"><h3>${icon('file-spreadsheet')}خروجی اکسل</h3></div>
          <div class="btn-col">
            <button class="btn btn-soft" data-csv-rep>${icon('wrench')}همه خرابی‌ها و تعمیرات</button>
            <button class="btn btn-soft" data-csv-an>${icon('clipboard-list')}همه تحلیل‌های خرابی</button>
            <button class="btn btn-soft" data-csv-logs>${icon('wrench')}همه سوابق تعویض قطعات</button>
          </div>
        </section>
        <section class="card danger-zone">
          <div class="card-head"><h3>${icon('triangle-alert')}بازنشانی</h3></div>
          <p class="muted small">همه اطلاعات پاک و سایت به حالت اولیه (اطلاعات فایل اکسل) برمی‌گردد. پیش از آن یک نسخه داخلی ذخیره می‌شود.</p>
          <button class="btn btn-ghost danger-text" data-reset>${icon('rotate-ccw')}بازنشانی کامل داده‌ها</button>
        </section>
      </div>
    </div>`;

  return {
    title: 'پشتیبان‌گیری و بازیابی',
    sub: 'نگهداری امن اطلاعات سایت آفلاین',
    html,
    mount(el) {
      el.querySelector('[data-export]').addEventListener('click', exportBackup);
      const on = (sel, fn) => { const b = el.querySelector(sel); if (b) b.addEventListener('click', fn); };
      on('[data-auto-choose]', async () => { if (await AutoBackup.choose()) { Toast.show('پشتیبان خودکار فعال شد'); App.rerender(); } });
      on('[data-auto-re]', async () => { if (await AutoBackup.reconnect()) { Toast.show('پشتیبان خودکار دوباره فعال شد'); App.rerender(); } });
      on('[data-auto-now]', async () => { if (await AutoBackup.writeNow()) Toast.show('در پوشه ذخیره شد'); App.rerender(); });
      on('[data-auto-off]', async () => { await AutoBackup.disconnect(); App.rerender(); });
      on('[data-csv-rep]', () => exportRepairsCSV(Rep.sorted(Store.get().repairs)));
      on('[data-csv-an]', () => exportAnalysesCSV(Logic.sorted(Store.get().analyses)));
      on('[data-csv-logs]', () => {
        const dd = Store.get();
        const rows = [['تاریخ', 'ماشین', 'مدل', 'سیستم', 'قطعه', 'کارکرد', 'شرح']];
        dd.partLogs.slice().sort((a, b) => (a.date || '').localeCompare(b.date || '')).forEach(l => {
          const m = Q.machine(l.machineId) || {}; const p = Q.part(m.model, l.partId) || {};
          rows.push([l.date, m.code, Q.modelName(m.model), Q.sys(p.sys).name, p.name, l.km ?? '', l.note]);
        });
        downloadCSV(`سوابق-تعویض-قطعات-${J.today().replace(/\//g, '-')}.csv`, rows);
      });
      on('[data-snap]', async () => { await Store.addSnapshot('manual'); Toast.show('نسخه داخلی ذخیره شد'); loadSnaps(); });
      on('[data-reset]', async () => {
        if (!await Modal.confirm({ title: 'بازنشانی کامل', message: 'همه تحلیل‌ها، سوابق، قطعات جایگزین و تنظیمات پاک می‌شوند. مطمئن هستید؟', ok: 'بله، بازنشانی شود', danger: true })) return;
        await Store.replaceAll(seedDB(), 'before-reset');
        Toast.show('داده‌ها بازنشانی شد');
      });

      /* بازیابی */
      const drop = el.querySelector('#drop'), fileIn = el.querySelector('#restoreFile');
      const handle = (file) => {
        if (!file) return;
        const r = new FileReader();
        r.onload = () => {
          let parsed;
          try { parsed = parseBackup(r.result); } catch (e) { Toast.show(e.message && e.message.includes('معتبر') ? e.message : 'فایل قابل خواندن نیست', 'danger', 5000); return; }
          const st = dataStats(parsed.data);
          Modal.open({
            title: 'بازیابی از فایل پشتیبان', icon: 'upload',
            body: `<p>فایل <b>${esc(file.name)}</b>${parsed.when ? ` (ذخیره‌شده در ${esc(toFa(parsed.when))})` : ''} شامل این اطلاعات است:</p>${statsList(st)}
              <div class="notice notice-warn">${icon('triangle-alert')}<span>اطلاعات فعلی سایت با محتوای این فایل <b>جایگزین</b> می‌شود. از وضعیت فعلی یک نسخه داخلی ذخیره خواهد شد.</span></div>`,
            footer: `<button class="btn btn-ghost" data-close>انصراف</button><button class="btn btn-primary" data-go>${icon('upload')}بازیابی شود</button>`,
            onMount(mel, api) {
              mel.querySelector('[data-go]').addEventListener('click', async () => {
                await Store.replaceAll(parsed.data, 'before-restore');
                api.close(); Toast.show('اطلاعات با موفقیت بازیابی شد');
              });
            },
          });
        };
        r.readAsText(file);
      };
      fileIn.addEventListener('change', () => { handle(fileIn.files[0]); fileIn.value = ''; });
      ['dragenter', 'dragover'].forEach(ev => drop.addEventListener(ev, e => { e.preventDefault(); drop.classList.add('over'); }));
      ['dragleave', 'drop'].forEach(ev => drop.addEventListener(ev, e => { e.preventDefault(); drop.classList.remove('over'); }));
      drop.addEventListener('drop', e => handle(e.dataTransfer.files[0]));

      /* نسخه‌های داخلی */
      const reasons = { daily: 'نسخه روزانه', manual: 'ذخیره دستی', 'before-restore': 'پیش از بازیابی', 'before-reset': 'پیش از بازنشانی', 'before-snapshot-restore': 'پیش از بازگشت به نسخه', 'before-upgrade': 'پیش از به‌روزرسانی سایت' };
      async function loadSnaps() {
        const box = el.querySelector('#snaps');
        let list = [];
        try { list = await Store.listSnapshots(); } catch (e) { list = []; }
        if (!list.length) { box.innerHTML = `<div class="calm">${icon('history')}<span>هنوز نسخه‌ای ذخیره نشده است.</span></div>`; return; }
        box.innerHTML = `<ul class="snap-list">${list.map(s => `<li>
          <span class="sn-ic">${icon(s.reason === 'daily' ? 'calendar' : s.reason === 'manual' ? 'bookmark' : 'shield')}</span>
          <div><b>${toFa(s.stamp)}</b><small>${reasons[s.reason] || s.reason} · ${nf((s.size || 0) / 1024, 1)} کیلوبایت · ${nf((s.data.analyses || []).length)} تحلیل</small></div>
          <span class="grow"></span>
          <button class="btn btn-sm btn-ghost" data-dl="${esc(s.id)}">${icon('download')}دانلود</button>
          <button class="btn btn-sm btn-soft" data-restore="${esc(s.id)}">${icon('rotate-ccw')}بازگشت</button>
        </li>`).join('')}</ul>`;
        box.querySelectorAll('[data-dl]').forEach(b => b.addEventListener('click', async () => {
          const s = await Store.getSnapshot(b.dataset.dl);
          downloadBlob(`نسخه-${s.stamp.replace(/[\/: ]/g, '-')}.json`, new Blob([JSON.stringify({ app: 'fleet-maint', version: 1, exportedAt: s.id, exportedAtFa: s.stamp, data: s.data })], { type: 'application/json' }));
        }));
        box.querySelectorAll('[data-restore]').forEach(b => b.addEventListener('click', async () => {
          const s = await Store.getSnapshot(b.dataset.restore);
          if (!await Modal.confirm({ title: 'بازگشت به نسخه', message: `اطلاعات به وضعیت ${toFa(s.stamp)} برگردد؟ از وضعیت فعلی هم یک نسخه ذخیره می‌شود.`, ok: 'بازگشت' })) return;
          await Store.replaceAll(s.data, 'before-snapshot-restore');
          Toast.show('به نسخه انتخابی بازگشت');
        }));
      }
      loadSnaps();
    },
  };
};

