Pages.defModels = () => {
  const d = Store.get();
  const ed = Auth.level('settings') >= 2;
  const html = `${setTabs('#/settings/models')}
    <section class="card">
      <div class="card-head"><h3>${icon('layers')}مدل‌های ماشین</h3><span class="muted small">فهرست قطعات نگهداری پیشگیرانه و قطعات جایگزین برای هر مدل جداست</span></div>
      <ul class="model-list">${d.models.map(m => {
    const ms = d.machines.filter(x => x.model === m.id);
    return `<li><span><b>${esc(m.name)}</b><small>${nf((d.catalog[m.id] || []).length)} قطعه · ${ms.map(x => esc(x.code)).join('، ') || 'بدون ماشین'}</small></span>
        <a class="btn btn-sm btn-ghost" href="#/parts/${esc(m.id)}">${icon('package')}قطعات</a>
        ${ed ? `<button class="icon-btn sm" data-rename="${esc(m.id)}" title="تغییر نام">${icon('pencil')}</button>${!ms.length ? `<button class="icon-btn sm danger" data-delmodel="${esc(m.id)}" title="حذف مدل">${icon('trash-2')}</button>` : ''}` : ''}</li>`;
  }).join('')}</ul>
    </section>`;
  return {
    title: 'تنظیمات و تعاریف', crumbs: setCrumb('مدل‌ها'), sub: 'مدل هر ماشین تعیین می‌کند کدام فهرست قطعات برایش استفاده شود',
    actions: ed ? `<button class="btn btn-primary" data-addmodel>${icon('plus')}مدل جدید</button>` : '',
    html,
    mount(el) {
      const nameModal = (md) => Modal.open({
        title: md ? 'تغییر نام مدل' : 'مدل جدید', icon: 'layers', size: 'sm',
        body: `<form class="form-grid cols-1" id="rn">${F.field('نام مدل', F.input('name', md ? md.name : '', 'placeholder="مثلاً لودر ZL50" autofocus'))}</form>`,
        footer: `<button class="btn btn-ghost" data-close>انصراف</button><button class="btn btn-primary" data-save>${icon('save')}ذخیره</button>`,
        onMount(mel, api) {
          const go = () => {
            const v = F.read(mel.querySelector('#rn')); const nm = v.name.trim();
            if (!nm) { Toast.show('نام مدل را بنویسید', 'warn'); return; }
            Store.update(dd => {
              if (md) dd.models.find(x => x.id === md.id).name = nm;
              else { const id = 'M' + Date.now().toString(36).toUpperCase(); dd.models.push({ id, name: nm, brand: '' }); dd.catalog[id] = []; }
            });
            api.close(); Toast.show('ذخیره شد');
          };
          mel.querySelector('[data-save]').addEventListener('click', go);
          mel.querySelector('#rn').addEventListener('submit', e => { e.preventDefault(); go(); });
        },
      });
      const am = el.querySelector('[data-addmodel]'); if (am) am.addEventListener('click', () => nameModal(null));
      el.querySelectorAll('[data-rename]').forEach(b => b.addEventListener('click', () => nameModal(Q.model(b.dataset.rename))));
      el.querySelectorAll('[data-delmodel]').forEach(b => b.addEventListener('click', async () => {
        const md = Q.model(b.dataset.delmodel);
        if (!await Modal.confirm({ title: 'حذف مدل', danger: true, message: `مدل «${esc(md.name)}» و فهرست قطعاتش حذف شود؟`, ok: 'حذف' })) return;
        Store.update(dd => { removeParts(dd, md.id, (dd.catalog[md.id] || []).map(p => p.id)); dd.models = dd.models.filter(x => x.id !== md.id); delete dd.catalog[md.id]; });
      }));
    },
  };
};

