Pages.defRules = () => {
  const d = Store.get();
  const s = d.settings;
  const rules = d.rules[RulesRole];
  const ruleEditor = SEVERITIES.map(sv => `
    <div class="rule-edit" data-sev="${sv.key}">
      <div class="re-head">${sevPill(sv.key)}<button type="button" class="btn btn-sm btn-ghost" data-addrule="${sv.key}">${icon('plus')}ردیف</button></div>
      <div class="re-rows">
        <div class="re-row re-labels"><span>از (بار)</span><span>تا (بار)</span><span>اقدام مدیریتی</span><span></span></div>
        ${(rules[sv.key] || []).map((r, i) => `
        <div class="re-row" data-i="${i}">
          <input class="input num" name="min" value="${toFa(r.min)}" inputmode="numeric">
          <input class="input num" name="max" value="${r.max === null || r.max === undefined ? '' : toFa(r.max)}" placeholder="به بالا" inputmode="numeric">
          <input class="input" name="action" value="${esc(r.action)}" list="act-list">
          <button type="button" class="icon-btn sm danger" data-rmrule="${i}" title="حذف ردیف">${icon('x')}</button>
        </div>`).join('')}
      </div>
    </div>`).join('');
  const html = `${setTabs('#/settings/rules')}
    <section class="card">
      <div class="card-head"><h3>${icon('gavel')}قوانین اقدامات مدیریتی</h3>
        <div class="seg">${[['driver', 'راننده'], ['pm', 'مسئول PM']].map(([k, l]) => `<button class="${RulesRole === k ? 'on' : ''}" data-role="${k}">${l}</button>`).join('')}</div>
      </div>
      <p class="muted small">بر اساس تعداد دفعات سهل‌انگاری هر نفر در هر سطح حساسیت، اقدام مدیریتی تعیین می‌شود.</p>
      <datalist id="act-list"><option value="تعهد کتبی"><option value="کسر پاداش"><option value="کسر حقوق"><option value="تعهد کتبی و کسر پاداش"><option value="تذکر شفاهی"></datalist>
      <div class="rules-editor" id="rulesEd">${ruleEditor}</div>
      <div class="form-grid" style="margin-top:14px">
        ${F.field('بازه شمارش دفعات', F.select('countWindow', [['all', 'از ابتدای ثبت سوابق (مانند اکسل)'], ['year', 'فقط در همان سال شمسی (هر سال از صفر)'], ['12m', '۱۲ ماه منتهی به هر بررسی']], s.countWindow))}
      </div>
      <div class="btn-row end">
        <button class="btn btn-ghost" data-rules-reset>${icon('rotate-ccw')}بازگشت به قوانین اکسل</button>
        <button class="btn btn-primary" data-rules-save>${icon('save')}ذخیره قوانین</button>
      </div>
    </section>`;
  return {
    title: 'تنظیمات و تعاریف', crumbs: setCrumb('قوانین اقدامات مدیریتی'), sub: 'اقدام مدیریتی متناسب با تعداد دفعات سهل‌انگاری',
    html,
    mount(el) {
      el.querySelectorAll('[data-role]').forEach(b => b.addEventListener('click', () => { RulesRole = b.dataset.role; App.rerender(); }));
      const readRules = () => {
        const out = {};
        $$('.rule-edit', el).forEach(box => {
          out[box.dataset.sev] = $$('.re-row[data-i]', box).map(r => {
            const v = F.read(r);
            return { min: num(v.min) || 1, max: v.max === '' ? null : num(v.max), action: v.action.trim() };
          }).filter(r => r.action);
        });
        return out;
      };
      const tmp = () => { const r = readRules(); Store.get().rules[RulesRole] = r; };
      el.querySelectorAll('[data-addrule]').forEach(b => b.addEventListener('click', () => {
        tmp();
        const list = Store.get().rules[RulesRole][b.dataset.addrule];
        const last = list[list.length - 1];
        const start = last ? ((last.max ?? last.min) + 1) : 1;
        if (last && (last.max === null || last.max === undefined)) last.max = start - 1 < last.min ? last.min : start - 1;
        list.push({ min: start, max: null, action: '' });
        App.rerender();
      }));
      el.querySelectorAll('[data-rmrule]').forEach(b => b.addEventListener('click', () => {
        tmp();
        const sev = b.closest('.rule-edit').dataset.sev;
        Store.get().rules[RulesRole][sev].splice(+b.dataset.rmrule, 1);
        App.rerender();
      }));
      el.querySelector('[data-rules-save]').addEventListener('click', () => {
        const r = readRules();
        const cw = el.querySelector('select[name=countWindow]').value;
        Store.update(dd => { dd.rules[RulesRole] = r; dd.settings.countWindow = cw; });
        Toast.show('قوانین ذخیره شد؛ اقدامات همه افراد دوباره محاسبه شد');
      });
      el.querySelector('[data-rules-reset]').addEventListener('click', async () => {
        if (!await Modal.confirm({ title: 'بازگشت به قوانین اکسل', message: `قوانین ${RulesRole === 'driver' ? 'راننده' : 'مسئول PM'} به مقادیر فایل اکسل برگردد؟` })) return;
        Store.update(dd => { dd.rules[RulesRole] = clone(DEFAULT_RULES[RulesRole]); });
      });
    },
  };
};


